    <section class="auth-dialog__content"><button class="auth-dialog__close" type="button" aria-label="Close account form">×</button><div class="auth-dialog__tabs" role="tablist"><button type="button" role="tab" id="login-tab" aria-controls="login-panel" aria-selected="true" data-auth-tab="login">Log in</button><button type="button" role="tab" id="register-tab" aria-controls="register-panel" aria-selected="false" data-auth-tab="register">Join EmberFans</button></div><form id="login-panel" class="auth-form auth-dialog__form is-active" method="POST" action="{{ route('login') }}" role="tabpanel" aria-labelledby="login-tab">@csrf<label>Email<input type="email" name="email" autocomplete="email" required></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label><label class="check"><input type="checkbox" name="remember"> Keep me signed in</label><button type="submit">Log in</button></form><form id="register-panel" class="auth-form auth-dialog__form" method="POST" action="{{ route('register') }}" role="tabpanel" aria-labelledby="register-tab" hidden>@csrf<label>Name<input name="name" autocomplete="name" required></label><label>Username<input name="username" autocomplete="username" required></label><label>Email<input type="email" name="email" autocomplete="email" required></label><label>Password<input type="password" name="password" autocomplete="new-password" required></label><label>Confirm password<input type="password" name="password_confirmation" autocomplete="new-password" required></label><label>I’m joining as<select name="role"><option value="fan">A fan</option><option value="creator">A creator</option></select></label><button type="submit">Create account</button></form></section>
  </div>
</dialog>
<script>
document.addEventListener('DOMContentLoaded',()=>{const dialog=document.getElementById('auth-dialog');if(!dialog||!dialog.showModal)return;const tabs=[...dialog.querySelectorAll('[data-auth-tab]')],panels={login:document.getElementById('login-panel'),register:document.getElementById('register-panel')};const select=(name)=>{tabs.forEach(tab=>tab.setAttribute('aria-selected',String(tab.dataset.authTab===name)));Object.entries(panels).forEach(([key,panel])=>{const active=key===name;panel.hidden=!active;panel.classList.toggle('is-active',active)});};document.querySelectorAll('a[href="{{ route('login') }}"],a[href="{{ route('register') }}"]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();select(link.href.endsWith('/register')?'register':'login');dialog.showModal();dialog.querySelector('input:not([type=hidden])')?.focus();}));tabs.forEach(tab=>tab.addEventListener('click',()=>select(tab.dataset.authTab)));dialog.querySelector('.auth-dialog__close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close();});});
</script>
